import json, collections
d=json.load(open('.archon-horizon/blueprints/Algebraic-Jacobian-Challenge.json'))
N={n['id']:n for n in d['nodes']}
P=[(e['source'],e['target']) for e in d['edges']]
adj=collections.defaultdict(list)
for a,b in P: adj[a].append(b)
def path(src,dst):
    q=collections.deque([[src]]); seen={src}
    while q:
        p=q.popleft()
        if p[-1]==dst: return p
        for y in adj[p[-1]]:
            if y not in seen: seen.add(y); q.append(p+[y])
for t in ['def:pic_zero_subscheme','thm:fga_pic_representability','def:Jacobian','def:divisor_degree_pic']:
    print(t,"<=",path('lem:pullback_tensor_map_isiso',t))
EOF
